#if UNITY_EDITOR
using UnityEditor;
using UnityEditor.Build;
using UnityEditor.Build.Reporting;
using UnityEngine;
using PixelCrushers.DialogueSystem;
using System.Collections.Generic;

// GENERATED BY GEMINI ARGON
public class DiceDialogueValidator : IPreprocessBuildWithReport
{
    // Determines the order in which pre-build scripts run. 0 = among the first.
    public int callbackOrder => 0;

    // This method is called automatically when you click "Build".
    public void OnPreprocessBuild(BuildReport report)
    {
        Debug.Log("[Dice System] Starting dialogue validation before build...");
        ValidateDialogueDatabases();
    }

    // This also adds a button to the Unity top menu so validation can be run
    // at any time without a build (Tools -> Dice System -> Validate Dialogues).
    [MenuItem("Tools/Dice System/Validate Dialogues")]
    public static void ValidateMenu()
    {
        ValidateDialogueDatabases();
        Debug.Log("[Dice System] Manual validation completed.");
    }

    private static void ValidateDialogueDatabases()
    {
        // 1. Find all valid colors from the project's ScriptableObjects.
        HashSet<string> validDiceTypes = new HashSet<string>();
        string[] dieGuids = AssetDatabase.FindAssets("t:StatDieDefinition");
        
        foreach (string guid in dieGuids)
        {
            string path = AssetDatabase.GUIDToAssetPath(guid);
            StatDieDefinition dieDef = AssetDatabase.LoadAssetAtPath<StatDieDefinition>(path);
            if (dieDef != null && !string.IsNullOrEmpty(dieDef.statDieType))
            {
                validDiceTypes.Add(dieDef.statDieType.ToLowerInvariant());
            }
        }

        if (validDiceTypes.Count == 0)
        {
            Debug.LogWarning("[Dice System] No dice ScriptableObjects were found. The system has nothing to compare against.");
            return;
        }

        // 2. Find all Dialogue Databases in the project.
        string[] dbGuids = AssetDatabase.FindAssets("t:DialogueDatabase");
        bool hasErrors = false;

        foreach (string guid in dbGuids)
        {
            string path = AssetDatabase.GUIDToAssetPath(guid);
            DialogueDatabase db = AssetDatabase.LoadAssetAtPath<DialogueDatabase>(path);
            
            if (db == null) continue;

            // 3. Iterate through all conversations and their nodes.
            foreach (Conversation conversation in db.conversations)
            {
                foreach (DialogueEntry entry in conversation.dialogueEntries)
                {
                    string targetType = Field.LookupValue(entry.fields, "DiceTarget")?.Trim();
                    string activeTypesCSV = Field.LookupValue(entry.fields, "DiceActive")?.Trim();

                    if (string.IsNullOrWhiteSpace(targetType) && string.IsNullOrWhiteSpace(activeTypesCSV))
                        continue;

                    // Validate DiceTarget.
                    if (!string.IsNullOrWhiteSpace(targetType) && !validDiceTypes.Contains(targetType.ToLowerInvariant()))
                    {
                        Debug.LogError($"[BUILD ERROR] Database '{db.name}', conversation '{conversation.Title}', node '{entry.MenuText}': DiceTarget '{targetType}' does not exist in the dice database!");
                        hasErrors = true;
                    }

                    // Validate DiceActive.
                    if (!string.IsNullOrWhiteSpace(activeTypesCSV))
                    {
                        string[] activeTypes = activeTypesCSV.Split(new[] { "," }, System.StringSplitOptions.RemoveEmptyEntries);
                        foreach (string t in activeTypes)
                        {
                            if (!validDiceTypes.Contains(t.Trim().ToLowerInvariant()))
                            {
                                Debug.LogError($"[BUILD ERROR] Database '{db.name}', conversation '{conversation.Title}', node '{entry.MenuText}': DiceActive contains an invalid color '{t.Trim()}'!");
                                hasErrors = true;
                            }
                        }
                    }
                }
            }
        }

        // 4. Result: If there is an error, stop the build immediately.
        if (hasErrors)
        {
            // Throwing BuildFailedException immediately stops the build process.
            throw new BuildFailedException("[Dice System] Build canceled! The dialogue databases contain dice errors. Check the red errors in the console.");
        }
    }
}
#endif
